function ActivityMidFestivalMgr:LoadMainQuestLevelVoByPlaceId(placeId)
    ---@type BaseSetting
    local setting = CfUtils.GetCfTable(AutoIds.IdSetting6086)
    local filters = setting:GetAll()
    local questVoList = {}
    for i, row in pairs(filters) do
        local __placeId = row:Get("placeId")
        if __placeId == placeId then
            local refId = checkNumber(row:GetPrimaryKey())
            local _setting = SettingMgr:GetInstance():GetSetting(AutoIds.IdSetting6086, "MidFestivalMainQuestLevelVo")
            local vo = _setting:Get(refId)
            table.insert(questVoList, vo)
        end
    end
    return questVoList
end

