end

function ActivityMidFestivalMgr:GetBossRankRewardCfByType(type)
    local allVoList = self:GetRankRewardList()
    local retVoList = {}
    for i, item in ipairs(allVoList) do
        ---@type MidFestivalBossRankRewardVo
        local vo = item
        if vo.type == type then
            table.insert(retVoList, vo)
        end
    end
    table.sort(retVoList, function(a, b)
        return a.id < b.id
    end)
    return retVoList
end

function ActivityMidFestivalMgr:GetRankRewardList()
    local allVos = CfUtils.GetCf(AutoIds.IdSetting6103, "MidFestivalBossRankRewardVo", true)
    ---@type ActivityMidFestivalComponent
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityMidFestivalComponent)
    local activityDojo = comp:GetActivityDojo()
    local data = {}
    for i, v in pairs(allVos) do
        if v.activityId == activityDojo.activityContentId then
            table.insert(data,v)
        end
    end
    return data
end

