function ActivityMidFestivalMgr:UpdateLetterRedPoint()
    -- 有红点的情况：NOW地图中存在NEW
    local homeDojo = self._activityMidFestivalComponent:GetHomeDojo()
    local hasRedPoint = false
    for _, map in ipairs(homeDojo.mapQuest) do
        if map.status == Constants.MidFestivalMapStatus.NOW then
            local subList = ActivityMidFestivalMgr:LoadMainQuestLevelVoByPlaceId(checkString(map.questId))
            local questOfNew = homeDojo:GetNewItemInSubList(subList)
            if isNotNull(questOfNew) then
                hasRedPoint = true
            end
            break
        end
    end
    CfUtils.WriteLocalData("MidFestivalLetterRedPoint", hasRedPoint and "true" or "false")
end

