function ActivityMidFestivalMgr:IsCanOneKeyDrawReward()
    -- 获取所有奖励
    local allRewards = self:GetBossHurtRewards()
    -- 获取所有可领取的奖励
    local historyMaxHurt = self:GetBossHurt()
    local allCanDrawButNotInListRewards = {}
    for _, reward in ipairs(allRewards) do
        ---@type MidFestivalBossDamageRewardVo
        local rewardVo = reward
        if historyMaxHurt >= checkNumber(rewardVo.upperLimit) and (not self:IsHaveDrawBossHurtReward(rewardVo.id)) then
            table.insert(allCanDrawButNotInListRewards, rewardVo)
        end
    end
    return table.count(allCanDrawButNotInListRewards) > 0
end

function ActivityMidFestivalMgr:IsHaveDrawBossHurtReward(rewardId)
    return self.activityBossData.hurtDrawRewardId[checkString(rewardId)] == 1
end

function ActivityMidFestivalMgr:DrawReward(rewardId)
    -- rewardId为0表示一键领取
    if checkNumber(rewardId) == 0 then
        -- 1. 获取所有奖励
        local allRewards = self:GetBossHurtRewards()
        -- 2. 获取所有可领取但未领取的奖励
        local allCanDrawButNotInListRewards = {}
        local historyMaxHurt = self:GetBossHurt()
        for i, reward in ipairs(allRewards) do
            ---@type MidFestivalBossDamageRewardVo
            local rewardVo = reward
            if checkNumber(historyMaxHurt) >= checkNumber(rewardVo.upperLimit) and (not self:IsHaveDrawBossHurtReward(rewardVo.id)) then
                table.insert(allCanDrawButNotInListRewards, rewardVo)
            end
        end
        -- 3. 将他们全部设置为已领取
        for _, rewardVo in ipairs(allCanDrawButNotInListRewards) do
            self.activityBossData.hurtDrawRewardId[checkString(rewardVo.id)] = 1
        end
        return
    end
    
    if not self:IsHaveDrawBossHurtReward(rewardId) then
        self.activityBossData.hurtDrawRewardId[checkString(rewardId)] = 1
    end
end

function ActivityMidFestivalMgr:DrawHurtReward(id,callBack)
    local activityDojo = self._activityMidFestivalComponent:GetActivityDojo()
    GameUtils.Request(Interfaces.OverseaMidFestivalBossDrawHurtReward, {activityUuid = activityDojo.id,rewardId = id} , function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        local rewards = jsonData.rewards
        self:DrawReward(id)
        
        if #rewards > 0 then
            GoodsUtils.DrawRewards(rewards)
            CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
        end
        local isCanOneKeyDraw = self:IsCanOneKeyDrawReward()
        self:UpdateBossHurtRedPoint(isCanOneKeyDraw)
        if callBack then
            callBack()
        end
    end)
end

