function ActivityMidFestivalMgr:UpdateBattleInfo(data)
    local homeDojo = self._activityMidFestivalComponent:GetHomeDojo()
    homeDojo.hpData.hp = data.activityHp
    if checkNumber(data.newMyRankInfo.hurt) > checkNumber(self:GetBossHurt()) then
        self.activityBossData.playerRank.hurt = checkNumber(data.newMyRankInfo.hurt)
    end
    local isCanOneKeyDraw = self:IsCanOneKeyDrawReward()
    self:UpdateBossHurtRedPoint(isCanOneKeyDraw)
